                const dStr = `${d.getDate()}/${d.getMonth() + 1}/${d.getFullYear()}`;
                const startMs = new Date(d.getFullYear(), d.getMonth(), d.getDate(), 0, 0, 0, 0).getTime();
                const endMs = new Date(d.getFullYear(), d.getMonth(), d.getDate(), 23, 59, 59, 999).getTime();
